insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('ReplyRight', 'reply-right', 'Answer customer emails in seconds, not hours', 'ReplyRight reads incoming customer emails and drafts on-brand responses instantly. Your team reviews and sends - cutting reply time by 80%. It learns your voice, knows your FAQs, and handles everything from billing questions to complaints with empathy and professionalism.', 'https://example.com/replyright', 'https://api.dicebear.com/7.x/shapes/svg?seed=replyright&backgroundColor=bfdbfe', 'Writing & Communication', ARRAY['E-commerce', 'SaaS', 'Customer Service'], ARRAY['Gmail', 'Outlook', 'Zendesk', 'Intercom', 'Freshdesk'], 'subscription', 'plug_and_play', true, 4.6, 318);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('BriefBot', 'brief-bot', 'Turn long reports into one-page executive summaries', 'BriefBot condenses lengthy documents, research reports, and email threads into crisp, decision-ready summaries. Upload a PDF or paste a link and get a structured brief in under 30 seconds. Used by executives, chiefs of staff, and consultants who need to stay informed without reading everything.', 'https://example.com/briefbot', 'https://api.dicebear.com/7.x/shapes/svg?seed=briefbot&backgroundColor=e0e7ff', 'Writing & Communication', ARRAY['Consulting', 'Finance', 'Executive', 'Legal'], ARRAY['Notion', 'Google Drive', 'Dropbox', 'Slack', 'Outlook'], 'freemium', 'plug_and_play', true, 4.4, 193);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('AgendaAI', 'agenda-ai', 'Build a structured meeting agenda in 60 seconds', 'AgendaAI creates clear, timed agendas from a quick description of your meeting goals. It suggests the right format based on meeting type - standup, brainstorm, decision meeting, or retrospective - and shares a clean agenda with attendees before the call.', 'https://example.com/agendaai', 'https://api.dicebear.com/7.x/shapes/svg?seed=agendaai&backgroundColor=d1fae5', 'Productivity & Meetings', ARRAY['Operations', 'Product', 'Executive', 'Consulting'], ARRAY['Google Calendar', 'Outlook Calendar', 'Slack', 'Notion', 'Microsoft Teams'], 'freemium', 'plug_and_play', true, 4.3, 142);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('FollowUp', 'followup', 'Never let a follow-up fall through the cracks again', 'FollowUp monitors your email and calendar, identifies commitments you made in meetings and emails, and sends you gentle reminders before things go stale. It tracks promises you make so you always follow through.', 'https://example.com/followup', 'https://api.dicebear.com/7.x/shapes/svg?seed=followup&backgroundColor=fef3c7', 'Productivity & Meetings', ARRAY['Sales', 'Consulting', 'Executive', 'HR'], ARRAY['Gmail', 'Outlook', 'Google Calendar', 'Slack'], 'subscription', 'plug_and_play', false, 4.0, 67);
insert into agents (name, slug, tagline, description, website, logo_url, category, industry_tags, platform_integrations, pricing_model, setup_complexity, verified, average_rating, review_count) values ('RecapAI', 'recap-ai', 'Your weekly work summary, written automatically', 'RecapAI pulls from your calendar, emails, and project tools to write a professional weekly update every Friday. Share it with your manager, your team, or keep it for your own records. No more staring at a blank page trying to remember what you accomplished.', 'https://example.com/recapai', 'https://api.dicebear.com/7.x/shapes/svg?seed=recapai&backgroundColor=cffafe', 'Productivity & Meetings', ARRAY['Operations', 'Marketing', 'Engineering', 'Finance'], ARRAY['Google Calendar', 'Jira', 'Notion', 'Slack', 'Asana', 'Gmail'], 'freemium', 'low', true, 4.5, 228);
